let profileCache: { ids: string[]; readAt: number } | undefined;
function accountProfiles() {
    if (profileCache && Date.now() - profileCache.readAt < PROFILE_CACHE_MS) return profileCache.ids;
    let ids = [DEFAULT_PROFILE];
