                  if (content) {
                    html += content;
                    response.innerHTML = formatHTML(html);
                    response.scrollTop = response.scrollHeight;
                  }
                } catch {}
              }
            }
          }
          response.innerHTML = formatHTML(html) + '<div class="done">Done</div>';
